function money(v){ return `₹${Math.round(v).toLocaleString('en-IN')}`; }
function findPlace(name){ const n=(name||'').trim().toLowerCase(); return LOCAL_PLACES.find(p=>p.name.toLowerCase()===n) || LOCAL_PLACES.find(p=>p.name.toLowerCase().includes(n)&&n.length>2); }
function haversine(a,b){ const R=6371, toRad=x=>x*Math.PI/180; const dLat=toRad(b.lat-a.lat), dLon=toRad(b.lon-a.lon); const s=Math.sin(dLat/2)**2+Math.cos(toRad(a.lat))*Math.cos(toRad(b.lat))*Math.sin(dLon/2)**2; return 2*R*Math.atan2(Math.sqrt(s),Math.sqrt(1-s)); }
function routeDistance(pickup, places, drop){ const start=(pickup||'').trim(), end=(drop||'').trim(); const names=[start,...places,end].map(x=>(x||'').trim()).filter(Boolean); let total=0, known=0, segments=0; for(let i=0;i<names.length-1;i++){ const a=findPlace(names[i]),b=findPlace(names[i+1]); if(a&&b){ total+=haversine(a,b); known++; } segments++; } const differentEndpoints=start && end && start.toLowerCase()!==end.toLowerCase(); let returnKm=0; if(differentEndpoints){ const a=findPlace(end),b=findPlace(start); if(a&&b){ returnKm=haversine(a,b); total+=returnKm; known++; } segments++; } return {km:total,known,segments,returnKm}; }
function childPct(age){ age=Number(age); if(!Number.isFinite(age)||age<0)return 0; if(age<=5)return 0; if(age<=11)return 0.6; return 1; }
function countedChild(age){ return Number(age)>6; }
function roomCount(adults, sharing){ const d={Single:1,Double:2,Triple:3,Quad:4}[sharing]||2; return Math.max(1,Math.ceil(adults/d)); }
function roomPlan(adults, ages, sharing, customRooms){ const extraBedChildren=ages.filter(a=>Number(a)>=6&&Number(a)<12).length; const adultEquivalentChildren=ages.filter(a=>Number(a)>=12).length; const totalAdults=Number(adults)+adultEquivalentChildren; const totalOccupants=totalAdults+extraBedChildren; const capacity={Single:1,Double:2,Triple:3,Quad:4}[sharing]||2; const baseRooms=roomCount(totalAdults,sharing); const rooms=customRooms?Math.max(1,Number(customRooms)):baseRooms; const extraBeds=extraBedChildren; return {extraBedChildren,adultEquivalentChildren,totalAdults,totalOccupants,baseRooms,rooms,roomCapacity:capacity,extraBeds}; }
function adjustedRoomRate(hotelType,sharing,food){ const h=HOTEL_RATES.find(x=>x.type===hotelType)||HOTEL_RATES[0]; return Number(h[sharing]||0)+(FOOD_ADJUSTMENTS[food]??0); }
function nights(days){ return Math.max(Number(days)-1,1); }
function minimumKm(days){ return Number(days)*250; }
function extraKm(actualKm,days){ return Math.max(Number(actualKm)-minimumKm(days),0); }
function vehicleCost(vehicle,days,actualKm,pickup,drop){ const km=actualKm>0?actualKm:minimumKm(days); const extra=extraKm(km,days); return Number(vehicle.dailyRate)*Number(days)+extra*Number(vehicle.extraKmRate); }
function hotelCost(hotelType,sharing,food,days,adults,ages,customRooms){ const rp=roomPlan(adults,ages,sharing,customRooms); const h=HOTEL_RATES.find(x=>x.type===hotelType)||HOTEL_RATES[0]; const rc=rp.rooms*adjustedRoomRate(hotelType,sharing,food)*nights(days); const eb=rp.extraBeds*Number(h.extraBed)*nights(days); return {cost:rc+eb,roomPlan:rp,roomRate:adjustedRoomRate(hotelType,sharing,food),nights:nights(days),extraBedCost:eb}; }
function calculatePackage(state){ const dist=routeDistance(state.pickup,state.places,state.drop); const v=VEHICLES.find(x=>x.name===state.vehicle)||VEHICLES[0]; const h=hotelCost(state.hotel,state.sharing,state.food,state.days,state.adults,state.childAges,state.rooms||null); const vc=vehicleCost(v,state.days,dist.km,state.pickup,state.drop); const base=vc+h.cost; const profit=base*0.40; const group=base+profit; /* The group package is the final package pool. Allocate that fixed pool by weighted passenger shares: adult=100%, child 0-5=0%, 6-11=60%, 12+=100%. */ const weightedShares=state.adults + state.childAges.reduce((s,a)=>s+childPct(a),0); const perAdult=weightedShares>0?group/weightedShares:group; const childrenCost=state.childAges.reduce((s,a)=>s+perAdult*childPct(a),0); const final=group; const finalPerAdult=perAdult; return {dist,vehicle:v,vehicleCost:vc,hotel:h,base,profit,groupPackageCost:group,childrenCost,final,finalPerAdult,weightedShares}; }
function sendWhatsApp(destination,extra=''){ const name=document.getElementById('name')?.value.trim()||''; const phone=document.getElementById('phone')?.value.trim()||''; const message=document.getElementById('message')?.value.trim()||''; const text=`Hello Vishwa Vikshanam Tours,\nI am interested in ${destination}.\nName: ${name}\nPhone / WhatsApp: ${phone}\nRequirements: ${message}\n${extra}`; window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(text)}`,'_blank'); }
function closeModal(){const m=document.getElementById('tourModal');m.classList.remove('open');m.setAttribute('aria-hidden','true');}
function displayStartingPrice(value){
  if(!value) return '';
  const s=String(value).trim();
  const m=s.match(/^(?:(\d+)\s*Nights?\s*\/\s*(\d+)\s*Days?\s*)?(?:Starting\s+from\s*)?(Rs\.?\s*[\d,]+\/-?)$/i);
  if(m){
    const duration=(m[1]&&m[2])?`${m[1]} Nights / ${m[2]} Days • `:'';
    return `${duration}Price: Starting from ${m[3]} + Taxes apply`;
  }
  if(/^Starting\s+from/i.test(s)) return `Price: ${s} + Taxes apply`;
  return `Price: Starting from ${s} + Taxes apply`;
}
function openTourModal(tour){ document.getElementById('modalTitle').textContent=tour.name; document.getElementById('modalPrice').textContent=displayStartingPrice(tour.startingPrice); document.getElementById('modalDescription').textContent=tour.description; const im=document.getElementById('modalImage');im.src=tour.image;im.alt=tour.name; document.getElementById('modalPlaces').innerHTML=tour.places.map(p=>`<li>${p}</li>`).join(''); document.getElementById('tourModal').classList.add('open'); document.getElementById('tourModal').setAttribute('aria-hidden','false'); window.currentModalTour=tour; }
function enquireTourOnWhatsApp(tour){ const text=`Hello Vishwa Vikshanam Tours,\nI want to Book / Enquire about: ${tour.name}\nPrice shown in app: ${tour.startingPrice||'Please confirm'}\nPlaces: ${tour.places.join(', ')}\nPlease share availability, itinerary and final price.`; window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(text)}`,'_blank'); }
function renderTours(){ const grid=document.getElementById('tourGrid'); grid.innerHTML=APP_TOURS.map((t,i)=>`<article class="card"><img src="${t.image}" alt="${t.name.replace(/"/g,'&quot;')}" loading="lazy"><div class="card-body"><h3>${t.name}</h3><p>${t.description}</p><div class="tour-price">${displayStartingPrice(t.startingPrice)}</div><button class="text-btn view-tour-btn" type="button" data-tour="${i}">View Tour Details →</button></div></article>`).join(''); document.querySelectorAll('.view-tour-btn').forEach(b=>b.addEventListener('click',()=>openTourModal(APP_TOURS[Number(b.dataset.tour)]))); document.getElementById('tourCount').textContent=`${APP_TOURS.length} tours`; }
function fillTourSelect(){const s=document.getElementById('customTour'); s.innerHTML='<option value="">Select a tour</option>'+APP_TOURS.map((t,i)=>`<option value="${i}">${t.name}</option>`).join(''); const d=document.getElementById('destination'); if(d)d.innerHTML='<option value="">Select tour</option>'+APP_TOURS.map(t=>`<option>${t.name}</option>`).join('')+'<option>Other</option>';}
function allPlaceOptions(){ const base=LOCAL_PLACES.map(p=>({name:p.name,type:'App Place'})); const seen=new Set(base.map(x=>x.name.toLowerCase())); const extra=INDIA_SEARCH_PLACES.filter(x=>{const k=x.name.toLowerCase(); if(seen.has(k)) return false; seen.add(k); return true;}); return base.concat(extra); }
function fillPlaces(){ const list=document.getElementById('placeList'); list.innerHTML=allPlaceOptions().map(p=>`<label class="place-option"><input type="checkbox" value="${p.name}"><span>${p.name}</span><small>${p.type}</small></label>`).join(''); document.querySelectorAll('#placeList input').forEach(x=>x.addEventListener('change',updateCalculator)); }
function selectedPlaces(){return [...document.querySelectorAll('#placeList input:checked')].map(x=>x.value)}
function renderTourPlaces(){ const i=Number(document.getElementById('customTour').value); const box=document.getElementById('tourSuggestedPlaces'); document.querySelectorAll('#placeList input').forEach(x=>x.checked=false); if(!Number.isInteger(i)||!APP_TOURS[i]){box.innerHTML='<strong>Our suggested tour places</strong><small>Select a tour to load its app sightseeing places.</small>'; return;} const places=APP_TOURS[i].places; box.innerHTML='<strong>Our suggested tour places</strong><div class="suggested-place-list">'+places.map(p=>`<label class="suggested-place"><input type="checkbox" value="${p}" data-suggested="1" checked> ${p}</label>`).join('')+'</div><small>Tick to keep a place, untick to remove it. Use “Places to Visit” below to add more places.</small>'; places.forEach(p=>{const existing=[...document.querySelectorAll('#placeList input')].find(x=>x.value===p); if(existing) existing.checked=true;}); box.querySelectorAll('input').forEach(x=>x.addEventListener('change',()=>{const main=[...document.querySelectorAll('#placeList input')].find(y=>y.value===x.value); if(main) main.checked=x.checked; updateCalculator();})); updateCalculator(); }
function updateAvailableVehicles(){const s=document.getElementById('vehicle'); const old=s.value; s.innerHTML=VEHICLES.map(v=>`<option value="${v.name}">${v.name}</option>`).join(''); if(old&&VEHICLES.some(v=>v.name===old))s.value=old;}
function buildChildInputs(){ const n=Math.max(0,Math.min(10,Number(document.getElementById('children').value)||0)); const box=document.getElementById('childAges'); box.innerHTML=Array.from({length:n},(_,i)=>`<input class="child-age" type="number" min="0" max="17" placeholder="Child ${i+1} age (0-17)">`).join(''); document.querySelectorAll('.child-age').forEach(x=>x.addEventListener('input',updateCalculator)); updateAvailableVehicles(); }
function updateCalculator(){ updateAvailableVehicles(); const ages=[...document.querySelectorAll('.child-age')].map(x=>x.value.trim()).filter(x=>x!=='').map(Number).filter(Number.isFinite); const tourIndex=Number(document.getElementById('customTour').value); const state={days:Number(document.getElementById('days').value)||1,adults:Number(document.getElementById('adults').value)||1,childAges:ages,pickup:document.getElementById('pickup').value,drop:document.getElementById('drop').value,places:selectedPlaces(),vehicle:document.getElementById('vehicle').value,hotel:document.getElementById('hotel').value,sharing:document.getElementById('sharing').value,food:document.getElementById('food').value,rooms:document.getElementById('rooms').value}; const r=calculatePackage(state); const tour=APP_TOURS[tourIndex]; document.getElementById('summaryTour').textContent=tour?.name||'Custom Tour'; document.getElementById('summaryDays').textContent=state.days; document.getElementById('summaryAdults').textContent=state.adults; document.getElementById('summaryChildren').textContent=ages.length?ages.map(a=>a+' yrs').join(', '):'0'; document.getElementById('summaryPickup').textContent=state.pickup||'—'; document.getElementById('summaryDrop').textContent=state.drop||'—'; document.getElementById('summaryVehicle').textContent=r.vehicle.name; document.getElementById('summaryHotel').textContent=state.hotel; document.getElementById('summaryFood').textContent=state.food; document.getElementById('summarySharing').textContent=state.sharing; document.getElementById('summaryPlaces').textContent=state.places.length?state.places.join(', '):'None'; const childBedEl=document.getElementById('childBedMessage'); if(childBedEl){ const bedCount=ages.filter(a=>a>=6&&a<=11).length; childBedEl.textContent=bedCount?`Extra mattress / bed will be provided for ${bedCount} child${bedCount===1?'':'ren'}. Bed cost is included internally in the package calculation.`:''; } document.getElementById('totalCost').textContent=money(r.final); document.getElementById('perAdultCost').textContent=money(r.finalPerAdult); window.currentQuote={state,r,tour}; }
function shareCustomQuote(){const q=window.currentQuote;if(!q)return; const s=q.state,r=q.r; const text=`Hello Vishwa Vikshanam Tours,
Custom Tour Enquiry / Quote
Tour: ${q.tour?.name||'Custom Tour'}
Days: ${s.days}
Adults: ${s.adults}
Children & Ages: ${s.childAges.join(', ')||'0'}
Pickup: ${s.pickup||'Not selected'}
Drop: ${s.drop||'Not selected'}
Suggested / Selected Places: ${s.places.join(', ')||'None'}
Vehicle: ${r.vehicle.name}
Hotel: ${s.hotel}
Food: ${s.food}
Room Sharing: ${s.sharing}
Total Package Cost: ${money(r.final)}
Per Adult Cost: ${money(r.finalPerAdult)}
Child Cost: ${money(r.childrenCost)}`; window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(text)}`,'_blank');}

function setupAutocomplete(inputId,listId){ const input=document.getElementById(inputId), list=document.getElementById(listId); if(!input||!list)return; const options=allPlaceOptions(); const render=()=>{const q=input.value.trim().toLowerCase(); if(!q){list.classList.remove('open');list.innerHTML='';return;} const hits=options.filter(x=>x.name.toLowerCase().includes(q)||x.type.toLowerCase().includes(q)).slice(0,30); list.innerHTML=hits.map(x=>`<button type="button" class="autocomplete-item" data-name="${x.name.replace(/"/g,'&quot;')}">${x.name}<small>${x.type}</small></button>`).join(''); list.classList.toggle('open',hits.length>0); list.querySelectorAll('.autocomplete-item').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.name;list.classList.remove('open');list.innerHTML='';updateCalculator();}));}; input.addEventListener('input',render); input.addEventListener('focus',render); document.addEventListener('click',e=>{if(!list.contains(e.target)&&e.target!==input)list.classList.remove('open');}); }

document.addEventListener('DOMContentLoaded',()=>{renderTours();fillTourSelect();fillPlaces();document.querySelectorAll('[data-close-modal]').forEach(x=>x.addEventListener('click',closeModal));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.getElementById('modalEnquire')?.addEventListener('click',()=>{if(window.currentModalTour)enquireTourOnWhatsApp(window.currentModalTour);});document.getElementById('tourSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();let n=0;document.querySelectorAll('#tourGrid .card').forEach(c=>{const show=c.innerText.toLowerCase().includes(q);c.hidden=!show;if(show)n++});document.getElementById('tourCount').textContent=`${n} tour${n===1?'':'s'}`});document.getElementById('customTour')?.addEventListener('change',renderTourPlaces);document.getElementById('children')?.addEventListener('change',buildChildInputs);document.getElementById('children')?.addEventListener('input',buildChildInputs);['days','adults','pickup','drop','vehicle','hotel','sharing','food','rooms'].forEach(id=>document.getElementById(id)?.addEventListener('input',updateCalculator));['vehicle','hotel','sharing','food','rooms'].forEach(id=>document.getElementById(id)?.addEventListener('change',updateCalculator));document.getElementById('shareQuote')?.addEventListener('click',shareCustomQuote);document.getElementById('enquiryForm')?.addEventListener('submit',e=>{e.preventDefault();sendWhatsApp(document.getElementById('destination').value)});document.getElementById('placeSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#placeList .place-option').forEach(x=>x.style.display=x.innerText.toLowerCase().includes(q)?'flex':'none');});setupAutocomplete('pickup','pickupSuggestions');setupAutocomplete('drop','dropSuggestions');buildChildInputs();updateCalculator();});
